import math


def annualised_vol(prices, periods=252):
    rets = [b / a - 1 for a, b in zip(prices, prices[1:])]
    n = len(rets)
    if n < 2:
        return 0.0
    mean = sum(rets) / n
    # Sample variance: divide by n - 1
    var = sum((r - mean) ** 2 for r in rets) / (n - 1)
    return math.sqrt(var) * math.sqrt(periods)
